CREATE TABLE bansir.fiscal_issuance_batches(tenant_id uuid NOT NULL,establishment_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),request_key uuid NOT NULL,created_by uuid NOT NULL,state text NOT NULL DEFAULT 'ready' CHECK(state IN('ready','running','paused','cancelled','completed')),input jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,establishment_id,id),UNIQUE(tenant_id,establishment_id,request_key));
CREATE TABLE bansir.fiscal_issuance_items(tenant_id uuid NOT NULL,establishment_id uuid NOT NULL,batch_id uuid NOT NULL,source_id uuid NOT NULL,position int NOT NULL,request_key uuid NOT NULL DEFAULT gen_random_uuid(),document_id uuid,PRIMARY KEY(tenant_id,establishment_id,batch_id,position),FOREIGN KEY(tenant_id,establishment_id,batch_id) REFERENCES bansir.fiscal_issuance_batches(tenant_id,establishment_id,id),FOREIGN KEY(tenant_id,establishment_id,source_id) REFERENCES bansir.fiscal_documents(tenant_id,establishment_id,id),FOREIGN KEY(tenant_id,establishment_id,document_id) REFERENCES bansir.fiscal_documents(tenant_id,establishment_id,id));
DO $$ DECLARE tab text;BEGIN FOREACH tab IN ARRAY ARRAY['fiscal_issuance_batches','fiscal_issuance_items'] LOOP EXECUTE format('ALTER TABLE bansir.%I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('ALTER TABLE bansir.%I FORCE ROW LEVEL SECURITY',tab);EXECUTE format('CREATE POLICY fiscal_unit ON bansir.%I TO bansir_runtime USING(bansir.can_access_establishment(tenant_id,establishment_id)) WITH CHECK(bansir.can_access_establishment(tenant_id,establishment_id))',tab);EXECUTE format('GRANT SELECT,INSERT,UPDATE ON bansir.%I TO bansir_runtime',tab);END LOOP;END $$;
CREATE UNIQUE INDEX fiscal_reference_once ON bansir.fiscal_issuance_items(tenant_id,establishment_id,source_id) WHERE document_id IS NOT NULL;
